    const uint64_t need =
      ((uint64_t) length + PAGE_SIZE - 1) & ~(PAGE_SIZE - 1);
    if (need > g_mmap_top - g_mmap_floor) ret = -ENOMEM;
    else {
      g_mmap_top -= need;
      memset((void*) (uintptr_t) g_mmap_top, 0, need);
      ret = (long) g_mmap_top;
    }
  }
  htif_uart_putc('M');
  dbg_hex(length);
  htif_uart_putc(' ');
  dbg_hex((unsigned long) ret);
  htif_uart_putc('\n');
  return ret;
}

long sys_munmap(unsigned long addr, unsigned long length)
