RoiMarkerPcs find_roi_markers(const std::string& elf_path) {
  RoiMarkerPcs out;
  std::vector<char> buf;
  Elf64_Ehdr eh;
  std::string ignored;  // never errors -- both fields staying 0 is the signal
  if (!read_elf64_header(elf_path, buf, eh, ignored)) return out;

  for (uint16_t i = 0; i < eh.e_phnum; ++i) {
    Elf64_Phdr ph;
    const size_t phoff = static_cast<size_t>(eh.e_phoff) +
                         static_cast<size_t>(i) * eh.e_phentsize;
    if (!load(buf, phoff, ph)) break;
    if (ph.p_type != PT_LOAD || (ph.p_flags & PF_X) == 0) continue;
    if (ph.p_offset + ph.p_filesz > buf.size()) continue;  // truncated file

    // Mirror hybrid::CsrTrigger::scan_buffer's own walk exactly: a 2-byte
    // stride, since RVC (compressed) instructions can leave a 4-byte
    // marker starting at a non-4-aligned offset. SLTI has no compressed
    // form, so a genuine marker is always the 4-byte case below.
    size_t off = 0;
    while (off + sizeof(uint16_t) <= ph.p_filesz) {
      uint16_t lo;
      std::memcpy(&lo, buf.data() + ph.p_offset + off, sizeof(lo));
      const bool is_32 = (lo & 0x3u) == 0x3u;
      if (is_32) {
        if (off + sizeof(uint32_t) > ph.p_filesz) break;
        uint32_t insn;
        std::memcpy(&insn, buf.data() + ph.p_offset + off, sizeof(insn));
        hybrid_handoff_kind kind = HYBRID_HANDOFF_NONE;
        if (hybrid_match_handoff_insn(insn, &kind)) {
          const uint64_t pc = ph.p_vaddr + off;
          if (kind == HYBRID_HANDOFF_ENTER) out.enter_pc = pc;
          else if (kind == HYBRID_HANDOFF_EXIT) out.exit_pc = pc;
        }
        off += sizeof(uint32_t);
      } else {
        off += sizeof(uint16_t);
      }
    }
  }
  return out;
}

}  // namespace andes_sim

