1	/* Trap glue shared by all C-level round-trip fixtures.
2	 *
3	 * crt0.S calls init_mtvec() directly, BEFORE the .init_array walk, so
4	 * the trap vector is live before any C++ static constructor runs;
5	 * trap.S's m_trap_entry tail-calls handle_trap on every exception or
6	 * interrupt. vplat_syscalls.c routes syscalls through direct MMIO
7	 * (UART + SimControl/HTIF), not through `ecall`, so there's no
8	 * syscall-dispatch table here. Any trap is treated as a fatal error:
9	 * print a diagnostic and exit.
10	 */
11	
12	#ifdef __cplusplus
13	extern "C"
14	{
15	#endif
16	
17	#include <stdint.h>
18	#include <stdio.h>
19	
20	#include "ecall_hook.h"
21	
22	#define WRITE_ERROR(format, ...) \
23	  fprintf(stderr, "\033[31m[ERROR] " format "\033[0m\n", ##__VA_ARGS__)
24	
25	#define CAUSE_ECALL_FROM_M_MODE 11UL
26	
27	__attribute__((used, noreturn)) void _exit(int exit_status);
28	
29	void exception_handler(void* tf)
30	{
31	  /* XLEN-wide so rv64 mepc/mtval are not truncated and the format is warning-
32	   * free on both ABIs (unsigned long is 32-bit on ilp32, 64-bit on lp64). */
33	  unsigned long mcause, mdcause, mepc, mtval;
34	
35	  asm volatile("csrr %0, mcause" : "=r"(mcause));
36	  asm volatile("csrr %0, mdcause" : "=r"(mdcause));
37	  asm volatile("csrr %0, mepc" : "=r"(mepc));
38	  asm volatile("csrr %0, mtval" : "=r"(mtval));
39	
40	  const unsigned long intbit = 1UL << (__riscv_xlen - 1);  /* mcause MSB */
41	
42	  WRITE_ERROR("Trap occurred!");
43	  WRITE_ERROR("mcause: 0x%lx", mcause);
44	  WRITE_ERROR("mdcause: 0x%lx", mdcause);
45	  WRITE_ERROR("mepc: 0x%lx", mepc);
46	  WRITE_ERROR("mtval: 0x%lx", mtval);
47	  if (tf) {
48	    const unsigned long* regs = (const unsigned long*) tf;
49	    WRITE_ERROR("ra: 0x%lx", regs[1]);
50	    WRITE_ERROR("a0: 0x%lx", regs[10]);
51	  }
52	
53	  if ((mcause & intbit) == 0) {
54	    WRITE_ERROR("Exception code: %lu", mcause);
55	  } else {
56	    WRITE_ERROR("Interrupt occurred! Cause: %lu", mcause & ~intbit);
57	  }
58	
59	  _exit((int) mcause);
60	}
61	
62	__attribute__((weak)) int handle_ecall(unsigned long* regs)
63	{
64	  (void) regs;
65	  return 0;
66	}
67	
68	void handle_trap(unsigned long cause, void* tf)
69	{
