1	#pragma once
2	
3	#include "memory_region.hpp"
4	
5	#include <spdlog/spdlog.h>
6	#include <systemc>
7	#include <tlm>
8	#include <tlm_utils/simple_target_socket.h>
9	
10	#include <cstdint>
11	
12	#include <array>
13	
14	/**
15	 * UART model (16550-compatible) for AE350 platform.
16	 *
17	 * Register map (from ae350.h UART_RegDef):
18	 *   0x00  IDREV   - ID and Revision Register (RO)
19	 *   0x10  CFG     - Hardware Configure Register (RO)
20	 *   0x14  OSCR    - Over Sample Control Register (RW)
21	 *   0x20  RBR/THR/DLL - Receiver Buffer / Transmitter Holding / Divisor Latch
22	 * LSB 0x24  IER/DLM - Interrupt Enable / Divisor Latch MSB 0x28  IIR/FCR -
23	 * Interrupt Identification / FIFO Control 0x2C  LCR     - Line Control Register
24	 *   0x30  MCR     - Modem Control Register
25	 *   0x34  LSR     - Line Status Register
26	 *   0x38  MSR     - Modem Status Register
27	 *   0x3C  SCR     - Scratch Register
28	 */
29	template<std::size_t BusWidth = 32>
30	class UART : public sc_core::sc_module
31	{
32	public:
33	  const MemoryRegion region;
34	  tlm_utils::simple_target_socket<UART, BusWidth> socket{"tsck"};
35	
36	  UART(const sc_core::sc_module_name& name, const MemoryRegion& region)
37	      : sc_core::sc_module{name}, region(region)
38	  {
39	    this->socket.register_b_transport(this, &UART::b_transport);
40	    reset();
41	  }
42	
43	  void b_transport(tlm::tlm_generic_payload& trans, sc_core::sc_time& /*delay*/)
44	  {
45	    handle_trans(trans);
46	    trans.set_response_status(tlm::TLM_OK_RESPONSE);
47	  }
48	
49	private:
50	  // Registers
51	  uint32_t idrev = 0x00112300; // some default ID
52	  uint32_t cfg = 0;
53	  uint32_t oscr = 0;
54	  uint32_t rbr = 0; // RBR (read) / THR (write) / DLL (when DLAB=1)
55	  uint32_t ier = 0; // IER (normal) / DLM (when DLAB=1)
56	  uint32_t iir =
57	    0x01; // IIR (read) / FCR (write), bit0=1 means no pending interrupt
58	  uint32_t lcr = 0;
59	  uint32_t mcr = 0;
60	  uint32_t lsr = 0;
61	  uint32_t msr = 0;
62	  uint32_t scr = 0;
63	
64	  // Internal state
65	  uint32_t dll = 0; // Divisor Latch LSB
66	  uint32_t dlm = 0; // Divisor Latch MSB
67	  bool fifo_enabled = false;
68	
69	  static constexpr uint32_t LSR_RDR = 0x01; // Receiver Data Ready
70	
71	  // THRE: 0 means the transmitter is still busy, 1 means it's ready to accept a
72	  // new character
73	  static constexpr uint32_t LSR_THRE =
74	    0x20; // Transmitter Holding Register Empty
75	  static constexpr uint32_t LSR_TEMT = 0x40; // Transmitter Empty
76	  static constexpr uint32_t LCR_DLAB = 0x80; // Divisor Latch Access Bit
77	
78	  void reset()
79	  {
80	    idrev = 0x00112300;
81	    cfg = 0;
82	    oscr = 0;
83	    rbr = 0;
84	    ier = 0;
85	    iir = 0x01;
86	    lcr = 0;
87	    mcr = 0;
88	    lsr = LSR_THRE | LSR_TEMT; // TX ready
89	    msr = 0;
90	    scr = 0;
91	    dll = 0;
92	    dlm = 0;
93	    fifo_enabled = false;
94	  }
95	
