    // extend to LMUL=8 (e.g. Andes ax45mpv: mtval decodes to the vfabs.v at
    // f32m8). QK8_0 is 32 elements, which is already an exact fit at LMUL=2
    // for any VLEN>=512, so this isn't worth re-deriving a narrower LMUL
    // grouping for -- use the portable scalar reference.
    quantize_row_q8_0_ref(x, y, k);
}

