Step qemu_step{kQemuId64, "fast-leg", trig};
Step vsim_step{acc->id, "accurate-leg", trig};
// --runtime linux + marker mode: vsim's OWN trigger only static-pre-scans
// whatever ELF it is handed (hybrid::CsrTrigger::scan_buffer, vsim_andesim
// src/hybrid/csr_trigger.hpp) -- but under --runtime linux vsim boots
// vlinux-run.elf, and the marker HINTs are in the APP's ELF, which vlinux
// only loads into memory at RUNTIME (never part of vlinux-run.elf's own
// static PT_LOAD content). QEMU1's plugin has no such limitation (a TCG
// plugin watches the EXECUTED instruction stream, content-agnostic), which
// is why only vsim's leg needs a workaround here. Fix: resolve the exit
// marker's PC by scanning elf_path (the app's real ELF) on the driver
// side, using the SAME shared predicate vsim's own scanner uses
// (hybrid/insn_match.h -- bit-for-bit the same match, not a reimplementation
// that could drift), and feed it to vsim through the EXISTING PC-mode
// trigger machinery (`--hybrid-exit-pc`, already wired for --trigger pc)
// instead of marker mode. QEMU1 keeps ordinary marker-mode unchanged (its
// detection already works); only vsim's own trigger config changes. This
// needs ZERO changes to vsim's own source, matching the roadmap's explicit
// "hybrid transport, triggers, plugin, resume driver, and engines need NO
// changes" constraint.
if (cli.runtime == "linux" && trig.kind == "marker") {
  const RoiMarkerPcs m = find_roi_markers(elf_path);
  if (m.exit_pc == 0)
    return fail("no ROI exit marker (slti x0,x0,0x5A1) found in " + elf_path +
                " -- add <andesim/ROI.h>'s andesim_ROI_begin()/end() around "
                "the region to measure");
  char pcbuf[32];
  std::snprintf(pcbuf, sizeof(pcbuf), "0x%llx",
                static_cast<unsigned long long>(m.exit_pc));
  vsim_step.trigger = Trigger{"pc", {{"exit_pc", pcbuf}}};
}
vsim_step.extra_args = std::move(vsim_extras);  // kanata, validated
// #1: with no --verify the driver consumes only the vsim mcycle delta, so ask
// the accurate leg to drain just the counters and skip the full register-file
// readback (~190 DM abstract commands). --verify keeps the full drain so the
// oracle diff sees every field. Driver policy lives here next to the rest of
// the verify reasoning, not in vsim_extra_args (user-forwarded flags only).
if (!cli.verify)
  vsim_step.extra_args.push_back("--drain-minimal");
// L4: the vsim leg speaks the same --log-level scale; forward ours so one
// flag tunes the whole pipeline (its stderr is relayed at <= debug).
vsim_step.extra_args.push_back("--log-level");
vsim_step.extra_args.push_back(std::to_string(log_threshold()));
plan.steps = {qemu_step, vsim_step};

